-- Shared application/network taxonomy; public metadata contains no contact data.
create table public.network_categories(code text primary key,label text not null,group_code text not null,group_label text not null,sort_order integer not null);
alter table public.network_categories enable row level security;
revoke all on public.network_categories from public,anon,authenticated;
grant select on public.network_categories to anon,authenticated;
create policy "network taxonomy public read" on public.network_categories for select to anon,authenticated using(true);
