alter table public.enterprise_applications
 add column industry_code text references public.network_categories(code),
 add column professional_codes text[] not null default '{}',
 add column network_public_consent boolean not null default false,
 add column network_public_description text,
 add column classification_hash text;
create index enterprise_application_industry_code on public.enterprise_applications(industry_code);

alter function private.submit_enterprise_registration(jsonb,uuid,uuid) rename to submit_enterprise_registration_base;
revoke all on function private.submit_enterprise_registration_base(jsonb,uuid,uuid) from public,anon,authenticated;
create function private.submit_enterprise_registration(p_details jsonb,p_request uuid,p_application uuid default null)
returns uuid language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid(); category public.network_categories%rowtype; codes text[]; consent boolean; summary text; fingerprint text; existing public.enterprise_applications%rowtype; result uuid; stripped jsonb;
begin
 if actor is null then raise exception 'authentication_required';end if;
 if p_details is null or jsonb_typeof(p_details)<>'object' or octet_length(p_details::text)>20000 or p_request is null then raise exception 'invalid_registration';end if;
 if jsonb_typeof(p_details->'industry_code') is distinct from 'string' then raise exception 'industry_category_required';end if;
 select * into category from public.network_categories where code=p_details->>'industry_code';
 if not found then raise exception 'invalid_industry_category';end if;
 if p_details ? 'professional_codes' then
  if jsonb_typeof(p_details->'professional_codes')<>'array' then raise exception 'invalid_professional_categories';end if;
  if jsonb_array_length(p_details->'professional_codes')>8 or exists(select 1 from jsonb_array_elements(p_details->'professional_codes') value where jsonb_typeof(value)<>'string') then raise exception 'invalid_professional_categories';end if;
 end if;
 select coalesce(array_agg(distinct value order by value),'{}') into codes from jsonb_array_elements_text(coalesce(p_details->'professional_codes','[]')) value where value<>category.code;
 if exists(select 1 from unnest(codes) as item(value) where not exists(select 1 from public.network_categories c where c.code=item.value)) then raise exception 'invalid_professional_categories';end if;
 if p_details ? 'network_public_consent' and jsonb_typeof(p_details->'network_public_consent')<>'boolean' then raise exception 'invalid_public_consent';end if;
 if p_details ? 'network_public_description' and jsonb_typeof(p_details->'network_public_description')<>'string' then raise exception 'invalid_public_description';end if;
 consent:=coalesce((p_details->>'network_public_consent')::boolean,false);summary:=nullif(btrim(p_details->>'network_public_description'),'');
 if length(summary)>500 or (consent and summary is null) then raise exception 'public_description_required';end if;
 fingerprint:=md5(p_details::text||coalesce(p_application::text,''));
 perform pg_advisory_xact_lock(hashtextextended('enterprise-registration:'||actor::text,0));
 select * into existing from public.enterprise_applications where registration_key=p_request for update;
 if found and (existing.requester_user_id<>actor or existing.classification_hash is distinct from fingerprint) then raise exception 'request_conflict';end if;
 stripped:=(p_details-array['industry_code','professional_codes','network_public_consent','network_public_description'])||jsonb_build_object('industry',category.group_label||'／'||category.label);
 result:=private.submit_enterprise_registration_base(stripped,p_request,p_application);
 if existing.id is not null then return result;end if;
 update public.enterprise_applications set industry_code=category.code,professional_codes=codes,network_public_consent=consent,network_public_description=summary,classification_hash=fingerprint where id=result;
 return result;
end;$$;
revoke all on function private.submit_enterprise_registration(jsonb,uuid,uuid) from public,anon;
grant execute on function private.submit_enterprise_registration(jsonb,uuid,uuid) to authenticated;

-- One organization may map to several categories, independently of its contact's personal nodes.
create table public.enterprise_network_entries(
 id uuid primary key default gen_random_uuid(),enterprise_id uuid not null references public.enterprises(id) on delete cascade,
 applicant_id uuid not null references public.profiles(id),category_code text not null references public.network_categories(code),
 is_primary boolean not null,display_name text not null,region text,website_url text,public_description text,
 public_visible boolean not null default false,updated_at timestamptz not null default now(),unique(enterprise_id,category_code)
);
alter table public.enterprise_network_entries enable row level security;
revoke all on public.enterprise_network_entries from public,anon,authenticated;
grant select on public.enterprise_network_entries to anon,authenticated;
create index enterprise_network_entries_applicant on public.enterprise_network_entries(applicant_id);
create index enterprise_network_entries_category on public.enterprise_network_entries(category_code);
create policy "approved consenting partner network entries" on public.enterprise_network_entries for select to anon,authenticated using(
 public_visible and exists(select 1 from public.enterprises e where e.id=enterprise_id and e.status='approved')
);
create policy "partner network mapping owner reviewer read" on public.enterprise_network_entries for select to authenticated using(
 applicant_id=(select auth.uid()) or private.is_admin('enterprise_reviewer') or private.is_admin('admin')
);
create function private.link_partner_network_categories() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if new.status='approved' and old.status is distinct from new.status and new.industry_code is not null then
  if not (private.is_admin('enterprise_reviewer') or private.is_admin('admin')) then raise exception 'admin_required';end if;
  -- Keep old mappings private when the reviewed organization classification changes.
  update public.enterprise_network_entries set public_visible=false,updated_at=now() where enterprise_id=new.enterprise_id;
  insert into public.enterprise_network_entries(enterprise_id,applicant_id,category_code,is_primary,display_name,region,website_url,public_description,public_visible)
   select new.enterprise_id,new.requester_user_id,code,code=new.industry_code,new.company_name,new.region,new.website_url,
    case when new.network_public_consent then new.network_public_description else null end,new.network_public_consent
   from unnest(array[new.industry_code]||new.professional_codes) code
   on conflict(enterprise_id,category_code) do update set applicant_id=excluded.applicant_id,is_primary=excluded.is_primary,display_name=excluded.display_name,region=excluded.region,website_url=excluded.website_url,public_description=excluded.public_description,public_visible=excluded.public_visible,updated_at=now();
 end if;
 return new;
end;$$;
revoke all on function private.link_partner_network_categories() from public,anon,authenticated;
create trigger partner_network_category_link after update of status on public.enterprise_applications for each row execute function private.link_partner_network_categories();

create view public.public_network_directory with(security_invoker=true) as
 select id,category,display_name,region,website_url,public_description from public.network_profiles where status='approved' and public_visible=true
 union all
 select id,category_code as category,display_name,region,website_url,public_description from public.enterprise_network_entries
 where public_visible=true and exists(select 1 from public.enterprises e where e.id=enterprise_id and e.status='approved');
revoke all on public.public_network_directory from public,anon,authenticated;
grant select on public.public_network_directory to anon,authenticated;

create function public.network_submit_categorized_profile(p_category text,p_display_name text,p_region text,p_website_url text,p_public_description text)
returns uuid language plpgsql security invoker set search_path='' as $$
begin
 if auth.uid() is null then raise exception 'authentication_required';end if;
 if not exists(select 1 from public.network_categories where code=p_category) then raise exception 'invalid_industry_category';end if;
 return public.network_submit_profile(p_category,p_display_name,p_region,p_website_url,p_public_description);
end;$$;
revoke all on function public.network_submit_categorized_profile(text,text,text,text,text) from public,anon;
grant execute on function public.network_submit_categorized_profile(text,text,text,text,text) to authenticated;
